try:
    validate([{"sku": "A", "qty": 1}, {"sku": "B", "qty": 0}, {"sku": "C", "qty": -4}])
except ExceptionGroup as _eg:
    assert _eg.message == "invalid rows"
    assert [_e.__notes__ for _e in _eg.exceptions] == [["row 1: sku=B"], ["row 2: sku=C"]], "each error needs one note naming its row and sku"
    assert all(str(_e) == "qty must be positive" for _e in _eg.exceptions)
else:
    raise AssertionError("bad rows must raise an ExceptionGroup")

