def load(order_id, qty):
    if qty <= 0:
        raise ValueError("qty must be positive")
    return qty

problems = []
for order_id, qty in [(1041, 3), (1042, 0), (1043, -2)]:
    try:
        load(order_id, qty)
    except ValueError as err:
        err.add_note(f"order {order_id}")
        err.add_note(f"qty received: {qty}")
        problems.append(err)

for err in problems:
    print(type(err).__name__, "-", err)
    for note in err.__notes__:
        print("   note:", note)

try:
    raise ExceptionGroup("orders", problems)
except* ValueError as grp:
    print("handled", len(grp.exceptions), "errors, first notes:", grp.exceptions[0].__notes__)
